INSERT INTO assessments(id,title) VALUES(1,'Financial foundations assessment');
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('1','Build a budget that works for you','Give every rupee a purpose without losing sight of everyday life.','1','Beginner','7','Separate needs from wants;Build a monthly plan;Review irregular expenses','A budget is a plan for your income. Begin with money you can reliably expect, then list essentials such as food, rent and transport. Separate flexible spending from commitments. If income varies, use a conservative estimate rather than your best month.
INSERT INTO assessments(id,title,lesson_id) VALUES(2,'Build a budget that works for you — knowledge check',1);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(1,1,1,'Which expense belongs in a budget?','Track before you cut. Plan for irregular costs. Review your budget regularly.',1);
INSERT INTO assessment_options(question_id,label,correct) VALUES(1,'Only rent',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(1,'All expected expenses, including annual costs',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(1,'Only expenses paid in cash',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(2,2,1,'Which expense belongs in a budget?','Track before you cut. Plan for irregular costs. Review your budget regularly.',1);
INSERT INTO assessment_options(question_id,label,correct) VALUES(2,'Only rent',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(2,'All expected expenses, including annual costs',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(2,'Only expenses paid in cash',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('2','Banking, without the jargon','Understand accounts, interest and the documents behind them.','2','Beginner','8','Compare account features;Understand interest;Protect account access','A bank account helps you receive, hold and transfer money. Before opening one, compare service charges, minimum balance rules, access options and the terms of the account. A savings account and a current account serve different needs.
INSERT INTO assessments(id,title,lesson_id) VALUES(3,'Banking, without the jargon — knowledge check',2);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(3,1,2,'Who should you share your bank OTP with?','Read charges and conditions. Use official channels. Keep authentication details private.',2);
INSERT INTO assessment_options(question_id,label,correct) VALUES(3,'A caller claiming to be a bank manager',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(3,'A delivery agent',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(3,'Nobody',true);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(4,3,2,'Who should you share your bank OTP with?','Read charges and conditions. Use official channels. Keep authentication details private.',2);
INSERT INTO assessment_options(question_id,label,correct) VALUES(4,'A caller claiming to be a bank manager',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(4,'A delivery agent',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(4,'Nobody',true);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('3','Your first emergency fund','Create a buffer for costs you cannot predict.','3','Beginner','9','Define an emergency;Choose accessible savings;Set a manageable goal','An emergency fund is money reserved for unexpected essential expenses or a temporary loss of income. It is different from money saved for a planned purchase. Start with an amount you can maintain and build gradually.
INSERT INTO assessments(id,title,lesson_id) VALUES(4,'Your first emergency fund — knowledge check',3);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(5,1,3,'What is an emergency fund primarily for?','Start small. Keep emergency money accessible. Replenish after using it.',3);
INSERT INTO assessment_options(question_id,label,correct) VALUES(5,'Unexpected essential expenses',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(5,'Daily entertainment',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(5,'Speculative trading',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(6,4,3,'What is an emergency fund primarily for?','Start small. Keep emergency money accessible. Replenish after using it.',3);
INSERT INTO assessment_options(question_id,label,correct) VALUES(6,'Unexpected essential expenses',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(6,'Daily entertainment',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(6,'Speculative trading',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('4','Fixed and recurring deposits','Compare lump-sum saving with regular contributions.','3','Intermediate','10','Distinguish FD and RD;Read withdrawal terms;Compare maturity values','A fixed deposit generally places a lump sum for an agreed term. A recurring deposit generally involves periodic contributions. Both require you to understand the institution’s terms, interest calculation and maturity conditions.
INSERT INTO assessments(id,title,lesson_id) VALUES(5,'Fixed and recurring deposits — knowledge check',4);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(7,5,3,'Which pattern usually fits a recurring deposit?','Match saving patterns. Check access restrictions. Read current terms.',4);
INSERT INTO assessment_options(question_id,label,correct) VALUES(7,'A regular monthly contribution',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(7,'An unlimited credit line',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(7,'Purchasing company shares',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('5','Understand the Public Provident Fund','Learn the purpose of PPF and what to verify before opening an account.','3','Intermediate','6','Recognize a long-term product;Find official terms;Check access rules','Public Provident Fund is a government small-savings product listed by India Post. It is intended for long-term saving. It should not be confused with an ordinary transaction account or an emergency cash balance.
INSERT INTO assessments(id,title,lesson_id) VALUES(6,'Understand the Public Provident Fund — knowledge check',5);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(8,6,3,'What should you check before opening PPF?','Verify official terms. Consider your time horizon. Do not assume instant access.',5);
INSERT INTO assessment_options(question_id,label,correct) VALUES(8,'Only the account name',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(8,'Current official terms and access rules',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(8,'An anonymous social media promise',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('6','Retirement planning and NPS','Understand contributions, investment risk and retirement income.','4','Intermediate','7','Explain contribution-based pensions;Identify investment risk;Find current NPS rules','Retirement planning considers expenses after regular employment income changes or stops. A contribution-based system builds a retirement balance from contributions and investment outcomes. The National Pension System is regulated by PFRDA.
INSERT INTO assessments(id,title,lesson_id) VALUES(7,'Retirement planning and NPS — knowledge check',6);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(9,1,4,'Are investment-linked returns always guaranteed?','Begin with your needs. Understand investment risk. Verify exit and withdrawal terms.',6);
INSERT INTO assessment_options(question_id,label,correct) VALUES(9,'Yes',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(9,'No',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(9,'Only if a friend recommends them',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(10,7,4,'Are investment-linked returns always guaranteed?','Begin with your needs. Understand investment risk. Verify exit and withdrawal terms.',6);
INSERT INTO assessment_options(question_id,label,correct) VALUES(10,'Yes',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(10,'No',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(10,'Only if a friend recommends them',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('7','Saving for a child’s future','Explore Sukanya Samriddhi through official information.','3','Intermediate','8','Identify long-term goals;Find eligibility rules;Compare access needs','India Post lists the Sukanya Samriddhi Account among government small-savings products. Understanding a product begins with its purpose and official eligibility rules. Do not assume a scheme applies solely because its name sounds relevant.
INSERT INTO assessments(id,title,lesson_id) VALUES(8,'Saving for a child’s future — knowledge check',7);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(11,8,3,'Where should current scheme eligibility be confirmed?','Check eligibility. Match the goal date. Keep official records.',7);
INSERT INTO assessment_options(question_id,label,correct) VALUES(11,'A forwarded message',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(11,'The official provider',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(11,'An advertisement without sources',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('8','Insurance: protection before promises','Make sense of premiums, coverage and exclusions.','5','Beginner','9','Explain risk pooling;Read exclusions;Distinguish insurance and investment','Insurance transfers specified risks under a contract in exchange for a premium. The policy wording defines covered events, exclusions, limits and the claims process. A low premium alone does not establish whether coverage meets your needs.
INSERT INTO assessments(id,title,lesson_id) VALUES(9,'Insurance: protection before promises — knowledge check',8);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(12,1,5,'What determines whether an event is covered?','Read the policy wording. Understand exclusions. Keep claims records.',8);
INSERT INTO assessment_options(question_id,label,correct) VALUES(12,'The policy terms',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(12,'The size of an advertisement',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(12,'The salesperson’s popularity',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(13,9,5,'What determines whether an event is covered?','Read the policy wording. Understand exclusions. Keep claims records.',8);
INSERT INTO assessment_options(question_id,label,correct) VALUES(13,'The policy terms',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(13,'The size of an advertisement',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(13,'The salesperson’s popularity',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('9','Income tax basics','Learn the vocabulary before you approach a tax return.','6','Beginner','10','Distinguish income and tax;Understand records;Find official guidance','Taxable income is determined by applicable rules, not simply by the balance in a bank account. Income sources, exemptions, deductions and the chosen regime can affect a calculation. Current rules must be checked for the relevant financial year.
INSERT INTO assessments(id,title,lesson_id) VALUES(10,'Income tax basics — knowledge check',9);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(14,1,6,'Which tax rules should be used for a return?','Use the correct financial year. Keep supporting records. Verify current rules.',9);
INSERT INTO assessment_options(question_id,label,correct) VALUES(14,'Those for the relevant financial year',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(14,'Any old social media chart',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(14,'Rules from another country',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(15,10,6,'Which tax rules should be used for a return?','Use the correct financial year. Keep supporting records. Verify current rules.',9);
INSERT INTO assessment_options(question_id,label,correct) VALUES(15,'Those for the relevant financial year',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(15,'Any old social media chart',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(15,'Rules from another country',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('10','Prepare for tax filing','Organize your information before submitting a return.','6','Intermediate','6','Gather records;Review prefilled data;Keep acknowledgements','Tax filing starts with understanding your income sources and selecting the applicable return under current rules. Gather statements and supporting records before entering figures. Prefilled information still needs to be checked.
INSERT INTO assessments(id,title,lesson_id) VALUES(11,'Prepare for tax filing — knowledge check',10);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(16,11,6,'Should prefilled return information be reviewed?','Check prefilled information. Complete required verification. Retain supporting evidence.',10);
INSERT INTO assessment_options(question_id,label,correct) VALUES(16,'No, it is always complete',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(16,'Yes, against your records',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(16,'Only if the amount is large',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('11','Digital payments with confidence','Check the recipient, amount and purpose before paying.','7','Beginner','7','Recognize authorization;Review recipient details;Keep transaction references','Digital payments can move money quickly. Before authorizing a transfer, check the recipient and amount on your own device. A request to enter a payment PIN is an authorization step and should not be treated as a way to receive a reward.
INSERT INTO assessments(id,title,lesson_id) VALUES(12,'Digital payments with confidence — knowledge check',11);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(17,12,7,'What should you check before authorizing payment?','Read before approving. Use trusted apps. Keep transaction references.',11);
INSERT INTO assessment_options(question_id,label,correct) VALUES(17,'Recipient and amount',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(17,'Only the caller’s confidence',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(17,'Nothing if the message is urgent',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('12','Spot a financial scam','Recognize urgency, impersonation and unrealistic promises.','7','Beginner','8','Identify warning signs;Verify independently;Protect credentials','Scams often create urgency or promise exceptional rewards. A familiar logo or caller name is not proof of identity. Stop and verify through a channel you obtained independently, such as the official provider’s website or branch.
INSERT INTO assessments(id,title,lesson_id) VALUES(13,'Spot a financial scam — knowledge check',12);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(18,1,7,'What is the safest response to an urgent account threat?','Pause under pressure. Verify independently. Never disclose authentication codes.',12);
INSERT INTO assessment_options(question_id,label,correct) VALUES(18,'Share the OTP immediately',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(18,'Verify independently with the bank',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(18,'Install software sent by the caller',false);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(19,13,7,'What is the safest response to an urgent account threat?','Pause under pressure. Verify independently. Never disclose authentication codes.',12);
INSERT INTO assessment_options(question_id,label,correct) VALUES(19,'Share the OTP immediately',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(19,'Verify independently with the bank',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(19,'Install software sent by the caller',false);
INSERT INTO lessons(id,title,description,topic_id,difficulty,duration,objectives,content,example,takeaways) VALUES('13','Navigate government schemes','Find reliable information and check whether a scheme is relevant.','8','Beginner','9','Locate official sources;Separate discovery and eligibility;Prepare questions','A scheme explorer can help discover programmes, but a search result is not an eligibility decision. Eligibility depends on current official rules and the applicant’s circumstances. Be wary of agents promising guaranteed approval.
INSERT INTO assessments(id,title,lesson_id) VALUES(14,'Navigate government schemes — knowledge check',13);
INSERT INTO assessment_questions(id,assessment_id,topic_id,prompt,explanation,position) VALUES(20,14,8,'Does appearing in search guarantee eligibility?','Discovery is a starting point. Check official eligibility. Keep application records.',13);
INSERT INTO assessment_options(question_id,label,correct) VALUES(20,'Yes',false);
INSERT INTO assessment_options(question_id,label,correct) VALUES(20,'No',true);
INSERT INTO assessment_options(question_id,label,correct) VALUES(20,'Only when bookmarked',false);
INSERT INTO government_schemes(id,title,category,beneficiaries,summary,eligibility,benefits,documents,procedure,faq,source_url) VALUES('1','Public Provident Fund (PPF)','Savings','Long-term savers','A small-savings product listed by India Post for long-term saving.','Verify current eligibility with the official provider. This demonstration catalogue does not determine individual eligibility.','See the official source for current terms. No rate, payout or tax benefit is guaranteed by FinIQ.','The official provider supplies the current document checklist. Do not upload identity documents to FinIQ.','Open the official source, review current conditions and use its authorized application channel.','Is this an eligibility decision? No. FinIQ provides educational discovery only.','https://www.indiapost.gov.in/banking-services/savings');
INSERT INTO policy_documents(scheme_id,title,content,source_url) VALUES('1','Public Provident Fund (PPF) overview','A small-savings product listed by India Post for long-term saving.','https://www.indiapost.gov.in/banking-services/savings');
INSERT INTO government_schemes(id,title,category,beneficiaries,summary,eligibility,benefits,documents,procedure,faq,source_url) VALUES('2','Sukanya Samriddhi Account','Women and child welfare','Families planning for a girl child','A government small-savings account listed by India Post. Confirm the current age and account-opening conditions.','Verify current eligibility with the official provider. This demonstration catalogue does not determine individual eligibility.','See the official source for current terms. No rate, payout or tax benefit is guaranteed by FinIQ.','The official provider supplies the current document checklist. Do not upload identity documents to FinIQ.','Open the official source, review current conditions and use its authorized application channel.','Is this an eligibility decision? No. FinIQ provides educational discovery only.','https://www.indiapost.gov.in/banking-services/savings');
INSERT INTO policy_documents(scheme_id,title,content,source_url) VALUES('2','Sukanya Samriddhi Account overview','A government small-savings account listed by India Post. Confirm the current age and account-opening conditions.','https://www.indiapost.gov.in/banking-services/savings');
INSERT INTO government_schemes(id,title,category,beneficiaries,summary,eligibility,benefits,documents,procedure,faq,source_url) VALUES('3','National Pension System (NPS)','Pensions','People planning for retirement','A contribution-based pension system regulated by PFRDA. Investment outcomes and applicable withdrawal rules matter.','Verify current eligibility with the official provider. This demonstration catalogue does not determine individual eligibility.','See the official source for current terms. No rate, payout or tax benefit is guaranteed by FinIQ.','The official provider supplies the current document checklist. Do not upload identity documents to FinIQ.','Open the official source, review current conditions and use its authorized application channel.','Is this an eligibility decision? No. FinIQ provides educational discovery only.','https://pfrda.org.in/en/schemes/national-pension-system/about-nps');
INSERT INTO policy_documents(scheme_id,title,content,source_url) VALUES('3','National Pension System (NPS) overview','A contribution-based pension system regulated by PFRDA. Investment outcomes and applicable withdrawal rules matter.','https://pfrda.org.in/en/schemes/national-pension-system/about-nps');
INSERT INTO government_schemes(id,title,category,beneficiaries,summary,eligibility,benefits,documents,procedure,faq,source_url) VALUES('4','Post Office Recurring Deposit','Savings','Regular savers','A recurring-deposit product listed among India Post savings services. Review deposit and premature-withdrawal conditions.','Verify current eligibility with the official provider. This demonstration catalogue does not determine individual eligibility.','See the official source for current terms. No rate, payout or tax benefit is guaranteed by FinIQ.','The official provider supplies the current document checklist. Do not upload identity documents to FinIQ.','Open the official source, review current conditions and use its authorized application channel.','Is this an eligibility decision? No. FinIQ provides educational discovery only.','https://www.indiapost.gov.in/banking-services/savings');
INSERT INTO policy_documents(scheme_id,title,content,source_url) VALUES('4','Post Office Recurring Deposit overview','A recurring-deposit product listed among India Post savings services. Review deposit and premature-withdrawal conditions.','https://www.indiapost.gov.in/banking-services/savings');
